#include <stdio.h>

int main(void) {
    long long A, B, C, D;
    if (scanf("%lld %lld %lld %lld", &A, &B, &C, &D) != 4) {
        return 0;
    }

    long long L = C - B;
    long long R = C - A;

    long long k = (L + D - 1) / D;
    if (k * D <= R) {
        printf("S\n");
    } else {
        printf("N\n");
    }

    return 0;
}
```

